/* Camada de identificação F: mesmas células legais e mesmas posições do PDF. */
(function(){
'use strict';
if(window.__bpfLegalFScreen)return;
window.__bpfLegalFScreen=true;
const layers=[{"left":11.47842,"top":55.28039,"width":81.25882,"height":12.61996,"src":"data:image/png;base64,"},{"left":11.47842,"top":32.91089,"width":81.25882,"height":21.18174,"src":"data:image/png;base64,"},{"left":11.47842,"top":36.96907,"width":81.25882,"height":27.61545,"src":"data:image/png;base64,"},{"left":11.47842,"top":36.96907,"width":81.25882,"height":27.61545,"src":"data:image/png;base64,"},{"left":11.47842,"top":36.96907,"width":81.25882,"height":27.61545,"src":"data:image/png;base64,"},{"left":11.47842,"top":36.96907,"width":81.25882,"height":27.61545,"src":"data:image/png;base64,"},{"left":11.47842,"top":34.98947,"width":81.25882,"height":19.35061,"src":"data:image/png;base64,"},{"left":11.47842,"top":41.25758,"width":81.25882,"height":28.00432,"src":"data:image/png;base64,"},{"left":11.47842,"top":41.25758,"width":81.25882,"height":28.00432,"src":"data:image/png;base64,"},{"left":11.47842,"top":41.49779,"width":81.25882,"height":21.90035,"src":"data:image/png;base64,"},{"left":11.47842,"top":41.47891,"width":81.25882,"height":21.89039,"src":"data:image/png;base64,"},{"left":11.47842,"top":70.62231,"width":81.25882,"height":20.78582,"src":"data:image/png;base64,"},{"left":11.47842,"top":78.49123,"width":81.25882,"height":12.422,"src":"data:image/png;base64,"}];
function apply(){
 for(const page of document.querySelectorAll('#pages > .page[data-page]')){
  const layer=layers[Number(page.dataset.page)];
  if(!layer||page.querySelector('.bpf-legal-f-screen'))continue;
  const background=page.querySelector('img.background');
  if(!background)continue;
  const image=document.createElement('img');
  image.className='bpf-legal-f-screen';image.alt='';image.setAttribute('aria-hidden','true');
  Object.assign(image.style,{position:'absolute',left:layer.left+'%',top:layer.top+'%',width:layer.width+'%',height:layer.height+'%',pointerEvents:'none',userSelect:'none'});
  image.src=layer.src;
  background.after(image);
 }
}
if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',apply,{once:true});
else apply();
const host=document.getElementById('pages');
if(host)new MutationObserver(apply).observe(host,{childList:true});
})();
